def match_parens(lst):
    # Step 1: Check if the input list contains only '(' or ')'
    if any(char not in ['(', ')'] for string in lst for char in string):
        return 'No'

    # Step 2: Concatenate the strings in the list
    concatenated_string = ''.join(lst)

    # Step 3: Check if the concatenated string forms a good string with balanced parentheses
    stack = []
    for char in concatenated_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
        return 'No'

